--
-- Name: fn_calculate_shipping_fee(double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_calculate_shipping_fee(p_distance_km double precision) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN CASE 
        WHEN p_distance_km < 2 THEN 0           -- Dưới 2km: Miễn phí (Ưu đãi nội khu)
        WHEN p_distance_km < 5 THEN 15000       -- 2km - 5km: 15.000đ (Giao nhanh nội thành)
        WHEN p_distance_km < 10 THEN 30000      -- 5km - 10km: 30.000đ (Nội thành xa)
        WHEN p_distance_km < 30 THEN 40000      -- 10km - 30km: 40.000đ (Ngoại thành/Lân cận)
        ELSE 50000                              -- Trên 30km: 50.000đ (Giao hàng liên tỉnh toàn quốc)
    END;
END; $$;


ALTER FUNCTION public.fn_calculate_shipping_fee(p_distance_km double precision) OWNER TO postgres;

--
-- Name: fn_check_qr_risk_score(uuid, numeric, numeric, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_check_qr_risk_score(p_uid uuid, p_new_lat numeric DEFAULT NULL::numeric, p_new_lng numeric DEFAULT NULL::numeric, p_new_time timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_max_scans_1m INT := 0;
    r RECORD;
    v_prev_lat DECIMAL; v_prev_lng DECIMAL; v_prev_time TIMESTAMP;
    v_dist FLOAT; v_time_diff_hours FLOAT;
BEGIN
    SELECT COALESCE(MAX(scan_count), 0) INTO v_max_scans_1m
    FROM (
        SELECT COUNT(*) OVER (
            ORDER BY thoi_gian_quet
            RANGE BETWEEN INTERVAL '1 minute' PRECEDING AND CURRENT ROW
        ) AS scan_count
        FROM (
            SELECT thoi_gian_quet
            FROM NhatKyXacThuc
            WHERE hop_thuoc_uid = p_uid
				AND thoi_gian_quet > NOW() - INTERVAL '24 hours'
            UNION ALL
            SELECT p_new_time
            WHERE p_new_time IS NOT NULL
        ) all_scans
    ) sub;

    IF v_max_scans_1m >= 10 THEN
        RETURN 100;
    END IF;

    SELECT toa_do_lat, toa_do_lng, thoi_gian_quet
    INTO v_prev_lat, v_prev_lng, v_prev_time
    FROM NhatKyXacThuc
    WHERE hop_thuoc_uid = p_uid
      AND toa_do_lat IS NOT NULL
    ORDER BY thoi_gian_quet DESC
    LIMIT 1;

    IF v_prev_lat IS NOT NULL AND p_new_lat IS NOT NULL THEN
        v_dist            := fn_tinh_khoang_cach_km(v_prev_lat, v_prev_lng, p_new_lat, p_new_lng);
        v_time_diff_hours := EXTRACT(EPOCH FROM (p_new_time - v_prev_time)) / 3600;

        IF v_time_diff_hours > 0 AND (v_dist / v_time_diff_hours) > 1000 THEN
            RETURN 100;
        END IF;
    END IF;

    IF p_new_lat IS NULL THEN
        v_prev_lat  := NULL;
        v_prev_lng  := NULL;
        v_prev_time := NULL;
        FOR r IN (
            SELECT toa_do_lat, toa_do_lng, thoi_gian_quet
            FROM NhatKyXacThuc
            WHERE hop_thuoc_uid = p_uid AND toa_do_lat IS NOT NULL
            ORDER BY thoi_gian_quet ASC
        ) LOOP
            IF v_prev_lat IS NOT NULL THEN
                v_dist            := fn_tinh_khoang_cach_km(v_prev_lat, v_prev_lng, r.toa_do_lat, r.toa_do_lng);
                v_time_diff_hours := EXTRACT(EPOCH FROM (r.thoi_gian_quet - v_prev_time)) / 3600;

                IF v_time_diff_hours > 0 AND (v_dist / v_time_diff_hours) > 1000 THEN
                    RETURN 100;
                END IF;
            END IF;
            v_prev_lat  := r.toa_do_lat;
            v_prev_lng  := r.toa_do_lng;
            v_prev_time := r.thoi_gian_quet;
        END LOOP;
    END IF;
    RETURN 0;
END; $$;


ALTER FUNCTION public.fn_check_qr_risk_score(p_uid uuid, p_new_lat numeric, p_new_lng numeric, p_new_time timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_find_nearest_pharmacies(numeric, numeric, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_find_nearest_pharmacies(p_lat numeric, p_lng numeric, p_duoc_pham_id integer, p_quy_cach_id integer) RETURNS TABLE(id integer, ten_nha_thuoc character varying, dia_chi text, khoang_cach double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_lat IS NULL OR p_lng IS NULL THEN
        RAISE EXCEPTION 'Tọa độ không hợp lệ';
    END IF;

    IF p_quy_cach_id IS NULL THEN
        RAISE EXCEPTION 'Quy cách sản phẩm không được để trống';
    END IF;

    RETURN QUERY
    WITH candidates AS (
        SELECT
            dv.id,
            dv.ten_don_vi,
            dv.dia_chi,
            fn_tinh_khoang_cach_km(p_lat, p_lng, dv.toa_do_lat, dv.toa_do_lng) AS kc
        FROM DonVi dv
        JOIN TonKho tk ON dv.id = tk.don_vi_id
        WHERE dv.loai_don_vi    = 'NhaThuoc'
          AND dv.toa_do_lat     IS NOT NULL
          AND dv.toa_do_lng     IS NOT NULL
          AND tk.duoc_pham_id   = p_duoc_pham_id
          AND tk.quy_cach_id    = p_quy_cach_id
          AND tk.so_luong_ton   > 0
    )
    SELECT c.id, c.ten_don_vi, c.dia_chi, ROUND(c.kc::NUMERIC, 2)::FLOAT
    FROM candidates c
    WHERE c.kc <= 50
    ORDER BY c.kc ASC
    LIMIT 5;
END; $$;


ALTER FUNCTION public.fn_find_nearest_pharmacies(p_lat numeric, p_lng numeric, p_duoc_pham_id integer, p_quy_cach_id integer) OWNER TO postgres;

--
-- Name: fn_get_loyalty_upgrade_progress(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_loyalty_upgrade_progress(p_khach_hang_id integer) RETURNS TABLE(hang_hien_tai character varying, hang_tiep_theo character varying, diem_con_thieu integer)
    LANGUAGE plpgsql
    AS $$
DECLARE 
    v_diem INT; 
    v_hang VARCHAR;
BEGIN
    -- 1. Truy vấn dữ liệu gốc của khách hàng
    SELECT diem_tich_luy, hang_thanh_vien INTO v_diem, v_hang 
    FROM KhachHang
    WHERE id = p_khach_hang_id;

    -- 2. Trả về bảng dữ liệu đã qua xử lý logic thăng hạng
    RETURN QUERY 
    SELECT 
        v_hang,
        -- Nếu đã là Kim Cương thì hạng tiếp theo vẫn là Kim Cương (Cấp bậc tối đa)
        CASE 
            WHEN v_hang = 'Đồng' THEN 'Bạc'::VARCHAR
            WHEN v_hang = 'Bạc' THEN 'Vàng'::VARCHAR
            WHEN v_hang = 'Vàng' THEN 'Bạch Kim'::VARCHAR
            WHEN v_hang = 'Bạch Kim' THEN 'Kim Cương'::VARCHAR
            ELSE 'Kim Cương'::VARCHAR 
        END,
        -- Tính toán số điểm cần thiết để đạt hạng tiếp theo
        CASE 
            WHEN v_hang = 'Đồng' THEN GREATEST(500 - v_diem, 0)
            WHEN v_hang = 'Bạc' THEN GREATEST(2000 - v_diem, 0)
            WHEN v_hang = 'Vàng' THEN GREATEST(5000 - v_diem, 0)
            WHEN v_hang = 'Bạch Kim' THEN GREATEST(10000 - v_diem, 0)
            ELSE 0 -- Đã đạt Kim Cương thì không còn điểm thiếu
        END;
END; 
$$;


ALTER FUNCTION public.fn_get_loyalty_upgrade_progress(p_khach_hang_id integer) OWNER TO postgres;

--
-- Name: fn_tinh_khoang_cach_km(numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tinh_khoang_cach_km(lat1 numeric, lon1 numeric, lat2 numeric, lon2 numeric) RETURNS double precision
    LANGUAGE plpgsql
    AS $$
DECLARE R FLOAT := 6371; dlat FLOAT; dlon FLOAT; a FLOAT; c FLOAT;
BEGIN dlat := radians(lat2 - lat1); dlon := radians(lon2 - lon1); a := sin(dlat/2) * sin(dlat/2) + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlon/2) * sin(dlon/2); c := 2 * atan2(sqrt(a), sqrt(1-a)); RETURN R * c; END; $$;


ALTER FUNCTION public.fn_tinh_khoang_cach_km(lat1 numeric, lon1 numeric, lat2 numeric, lon2 numeric) OWNER TO postgres;

--
-- Name: fn_tinh_tien_thanh_toan(integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tinh_tien_thanh_toan(p_khach_hang_id integer, p_ma_voucher character varying, p_diem_su_dung integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE v_tong DECIMAL := 0; v_giam DECIMAL := 0; v_loai VARCHAR; v_phai_tra DECIMAL;
BEGIN SELECT COALESCE(SUM(ctg.so_luong * qc.gia_ban), 0) INTO v_tong FROM ChiTietGioHang ctg JOIN QuyCachDongGoi qc ON ctg.quy_cach_id = qc.id WHERE ctg.khach_hang_id = p_khach_hang_id; IF p_ma_voucher IS NOT NULL AND p_ma_voucher != '' THEN SELECT loai_giam_gia, gia_tri INTO v_loai, v_giam FROM KhuyenMai WHERE ma_code = p_ma_voucher AND CURRENT_TIMESTAMP BETWEEN ngay_bat_dau AND ngay_ket_thuc AND so_luong_da_dung < so_luong_gioi_han; IF FOUND AND v_loai = 'PhanTram' THEN v_giam := v_tong * (v_giam / 100); END IF; END IF; v_phai_tra := v_tong - v_giam - (p_diem_su_dung * 100); RETURN GREATEST(v_phai_tra, 0); END; $$;


ALTER FUNCTION public.fn_tinh_tien_thanh_toan(p_khach_hang_id integer, p_ma_voucher character varying, p_diem_su_dung integer) OWNER TO postgres;

--
-- Name: fn_tinh_tong_ton_kho(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tinh_tong_ton_kho(p_duoc_pham_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE v_tong_ton INT; BEGIN SELECT COALESCE(SUM(so_luong_ton), 0) INTO v_tong_ton FROM TonKho WHERE duoc_pham_id = p_duoc_pham_id; RETURN v_tong_ton; END; $$;


ALTER FUNCTION public.fn_tinh_tong_ton_kho(p_duoc_pham_id integer) OWNER TO postgres;

--
-- Name: fn_truy_vet_nha_may(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_truy_vet_nha_may(p_uid uuid) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE v_ten_nha_may VARCHAR; BEGIN SELECT dv.ten_don_vi INTO v_ten_nha_may FROM HopThuoc ht JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id JOIN DuocPham dp ON lt.duoc_pham_id = dp.id JOIN DonVi dv ON dp.don_vi_san_xuat_id = dv.id WHERE ht.uid = p_uid; RETURN COALESCE(v_ten_nha_may, 'Mã không hợp lệ!'); END; $$;


ALTER FUNCTION public.fn_truy_vet_nha_may(p_uid uuid) OWNER TO postgres;

--
-- Name: sp_bao_cao_doanh_thu_control_break(date, date); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_bao_cao_doanh_thu_control_break(IN p_tu_ngay date DEFAULT NULL::date, IN p_den_ngay date DEFAULT NULL::date)
    LANGUAGE plpgsql
    AS $$
DECLARE
	cur_ct CURSOR FOR
	SELECT kh.id AS kh_id, kh.ho_ten, dh.id AS don_id, dh.tong_tien AS thanh_tien
	FROM DonHang dh
	JOIN KhachHang kh ON dh.khach_hang_id = kh.id
	WHERE dh.trang_thai_don = 'HoanThanh'
	  AND (p_tu_ngay IS NULL OR dh.ngay_dat_hang >= p_tu_ngay)
	  AND (p_den_ngay IS NULL OR dh.ngay_dat_hang < p_den_ngay + 1)
	ORDER BY kh.id, dh.id;
		
    v_kh_id INT; v_ho_ten VARCHAR; v_don_id INT; v_thanh_tien DECIMAL;
    v_kh_prev INT := NULL; v_ten_prev VARCHAR; v_subtotal DECIMAL := 0; v_grand DECIMAL := 0;
BEGIN
    RAISE NOTICE 'Doanh thu từ % đến %',
        COALESCE(p_tu_ngay::TEXT, 'đầu'),
        COALESCE(p_den_ngay::TEXT, 'nay');

    OPEN cur_ct;
    LOOP
        FETCH cur_ct INTO v_kh_id, v_ho_ten, v_don_id, v_thanh_tien;
        EXIT WHEN NOT FOUND;

        IF v_kh_prev IS NOT NULL AND v_kh_id <> v_kh_prev THEN
            RAISE NOTICE '-> Tổng KH % (%): %', v_kh_prev, v_ten_prev, v_subtotal;
        END IF;

        RAISE NOTICE ' Đơn % - KH % - Thành tiền %', v_don_id, v_kh_id, v_thanh_tien;

        v_subtotal := v_subtotal + v_thanh_tien;
        v_grand := v_grand + v_thanh_tien;
        v_kh_prev := v_kh_id;
        v_ten_prev := v_ho_ten;
    END LOOP;
    CLOSE cur_ct;

    IF v_kh_prev IS NOT NULL THEN
        RAISE NOTICE '-> Tổng KH % (%): %', v_kh_prev, v_ten_prev, v_subtotal;
    END IF;

    RAISE NOTICE 'Tổng doanh thu từ % đến %: %',
        COALESCE(p_tu_ngay::TEXT, 'đầu'),
        COALESCE(p_den_ngay::TEXT, 'nay'),
        v_grand;
END; $$;


ALTER PROCEDURE public.sp_bao_cao_doanh_thu_control_break(IN p_tu_ngay date, IN p_den_ngay date) OWNER TO postgres;

--
-- Name: sp_cap_nhat_lo_het_han(); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_cap_nhat_lo_het_han()
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE LoThuoc SET trang_thai = 'HetHan'
    WHERE han_su_dung < CURRENT_DATE
        AND trang_thai = 'HopLe';

    -- Trừ TonKho cho các hộp 'TrongKho' thuộc lô vừa hết hạn
    UPDATE TonKho tk
    SET so_luong_ton  = GREATEST(tk.so_luong_ton - sub.sl, 0),
        ngay_cap_nhat = CURRENT_TIMESTAMP
    FROM (
        SELECT ht.don_vi_hien_tai_id AS don_vi_id,
               lt.duoc_pham_id, lt.quy_cach_id, COUNT(*) AS sl
        FROM HopThuoc ht
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        WHERE lt.trang_thai = 'HetHan'
          AND ht.trang_thai = 'TrongKho'
        GROUP BY ht.don_vi_hien_tai_id, lt.duoc_pham_id, lt.quy_cach_id
    ) sub
    WHERE tk.don_vi_id    = sub.don_vi_id
      AND tk.duoc_pham_id = sub.duoc_pham_id
      AND tk.quy_cach_id  = sub.quy_cach_id;

    -- Đánh dấu HuyBo và ghi lịch sử phân phối trong một bước
    WITH hop_vua_huy AS (
        UPDATE HopThuoc ht
        SET trang_thai = 'HuyBo'
        FROM LoThuoc lt
        WHERE ht.lo_thuoc_id = lt.id
          AND lt.trang_thai  = 'HetHan'
          AND ht.trang_thai  = 'TrongKho'
        RETURNING ht.uid, ht.don_vi_hien_tai_id
    )
    SELECT uid, don_vi_hien_tai_id, 'XuatHuy', 'Tự động hủy: thuộc lô đã hết hạn sử dụng'
    FROM hop_vua_huy;
END; $$;


ALTER PROCEDURE public.sp_cap_nhat_lo_het_han() OWNER TO postgres;

--
-- Name: sp_dong_goi_don_hang(integer, uuid[]); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_dong_goi_don_hang(IN p_don_hang_id integer, IN p_mang_uid uuid[])
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_trang_thai_don VARCHAR(50);
    v_mismatch RECORD;
    v_count INT;
BEGIN
    SELECT trang_thai_don INTO v_trang_thai_don
    FROM DonHang WHERE id = p_don_hang_id;

    IF v_trang_thai_don IS NULL THEN
        RAISE EXCEPTION 'Đơn hàng ID % không tồn tại!', p_don_hang_id;
    END IF;

    IF v_trang_thai_don != 'ChoXacNhan' THEN
        RAISE EXCEPTION 'Chỉ có thể đóng gói đơn ở trạng thái ChoXacNhan. Hiện tại: %',
            v_trang_thai_don;
    END IF;

    IF EXISTS (
        SELECT 1 FROM HopThuoc
        WHERE uid = ANY(p_mang_uid)
          AND (trang_thai NOT IN ('TrongKho', 'XuatXuong') OR don_hang_id IS NOT NULL)
    ) THEN
        RAISE EXCEPTION 'Có hộp thuốc không khả dụng (đã bán, đang giao hoặc thuộc đơn hàng khác)!';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(p_mang_uid) AS list(uid)
        JOIN HopThuoc ht ON list.uid = ht.uid
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        WHERE (lt.duoc_pham_id, lt.quy_cach_id) NOT IN (
            SELECT duoc_pham_id, quy_cach_id
            FROM ChiTietDonHang
            WHERE don_hang_id = p_don_hang_id
        )
    ) THEN
        RAISE EXCEPTION 'Có hộp thuốc sai loại hoặc sai quy cách so với đơn hàng!';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(p_mang_uid) AS list(uid)
        JOIN HopThuoc ht ON list.uid = ht.uid
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        JOIN ChiTietDonHang ctd
            ON lt.duoc_pham_id = ctd.duoc_pham_id
           AND lt.quy_cach_id  = ctd.quy_cach_id
           AND ctd.don_hang_id = p_don_hang_id
        WHERE ht.don_vi_hien_tai_id <> ctd.don_vi_xuat_id
    ) THEN
        RAISE EXCEPTION 'Có hộp thuốc không thuộc kho xuất hàng của đơn!';
    END IF;

    SELECT ctd.duoc_pham_id, ctd.quy_cach_id, ctd.so_luong AS can_dong_goi, COALESCE(box.so_hop, 0) AS thuc_te INTO v_mismatch
    FROM ChiTietDonHang ctd
    LEFT JOIN (
        SELECT lt.duoc_pham_id, lt.quy_cach_id, COUNT(*) AS so_hop
        FROM unnest(p_mang_uid) AS list(uid)
        JOIN HopThuoc ht ON list.uid = ht.uid
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        GROUP BY lt.duoc_pham_id, lt.quy_cach_id
    ) box ON ctd.duoc_pham_id = box.duoc_pham_id
         AND ctd.quy_cach_id  = box.quy_cach_id
    WHERE ctd.don_hang_id = p_don_hang_id
      AND ctd.so_luong != COALESCE(box.so_hop, 0)
    LIMIT 1;

    IF FOUND THEN
        RAISE EXCEPTION 'Số lượng không khớp: sản phẩm ID % (quy cách: %). Cần % hộp, thực tế: % hộp',
            v_mismatch.duoc_pham_id, v_mismatch.quy_cach_id,
            v_mismatch.can_dong_goi, v_mismatch.thuc_te;
    END IF;

    SELECT uid, don_vi_hien_tai_id, 'DongGoi', 'Đóng gói cho đơn hàng ID: ' || p_don_hang_id
    FROM HopThuoc
    WHERE uid = ANY(p_mang_uid);

    UPDATE HopThuoc
    SET don_hang_id = p_don_hang_id,
        trang_thai  = 'DaDongGoi'
    WHERE uid = ANY(p_mang_uid)
      AND trang_thai IN ('TrongKho', 'XuatXuong')
      AND don_hang_id IS NULL;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> array_length(p_mang_uid, 1) THEN
        RAISE EXCEPTION 'Xung đột: % hộp thuốc vừa bị tiến trình khác lấy mất. Vui lòng thử lại.',
            array_length(p_mang_uid, 1) - v_count;
    END IF;

    UPDATE DonHang SET trang_thai_don = 'DaDongGoi' WHERE id = p_don_hang_id;

END; $$;


ALTER PROCEDURE public.sp_dong_goi_don_hang(IN p_don_hang_id integer, IN p_mang_uid uuid[]) OWNER TO postgres;

--
-- Name: sp_generate_pharma_uids(integer, integer, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_generate_pharma_uids(IN p_lo_thuoc_id integer, IN p_so_luong integer, IN p_don_vi_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE 
    v_uid UUID;
BEGIN 
    FOR i IN 1..p_so_luong LOOP 
        VALUES (p_lo_thuoc_id, p_don_vi_id, 'XuatXuong') 
        RETURNING uid INTO v_uid;

        VALUES (v_uid, p_don_vi_id, 'KhoiTao', 'Khởi tạo định danh UID cho từng hộp thuốc thuộc lô thuốc #' || p_lo_thuoc_id); 
    END LOOP; 
END; $$;


ALTER PROCEDURE public.sp_generate_pharma_uids(IN p_lo_thuoc_id integer, IN p_so_luong integer, IN p_don_vi_id integer) OWNER TO postgres;

--
-- Name: sp_hoan_thanh_don_hang(integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_hoan_thanh_don_hang(IN p_don_hang_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_khach_hang_id INT;
    v_trang_thai_hien_tai VARCHAR(50);
BEGIN
    SELECT khach_hang_id, trang_thai_don
    INTO v_khach_hang_id, v_trang_thai_hien_tai
    FROM DonHang
    WHERE id = p_don_hang_id;

    IF v_trang_thai_hien_tai IS NULL THEN
        RAISE EXCEPTION 'Lỗi: Đơn hàng không tồn tại!';
    END IF;
    IF v_trang_thai_hien_tai != 'DangGiao' THEN
        RAISE EXCEPTION 'Lỗi: Chỉ có thể hoàn thành đơn hàng đang ở trạng thái DangGiao. Trạng thái hiện tại: %',
            v_trang_thai_hien_tai;
    END IF;

    UPDATE DonHang
    SET trang_thai_don = 'ChoHoanTat',
        trang_thai_thanh_toan = 'DaThanhToan'
    WHERE id = p_don_hang_id;

    UPDATE HopThuoc
    SET trang_thai = 'DaBan'
    WHERE don_hang_id = p_don_hang_id;

    SELECT uid, 'GiaoHangThanhCong', 'Giao hàng thành công - Đơn hàng #' || p_don_hang_id
    FROM HopThuoc
    WHERE don_hang_id = p_don_hang_id;
	
    UPDATE DuocPham dp
    SET so_luong_da_ban   = dp.so_luong_da_ban + sub.tong_sl,
        ngay_cap_nhat_moi = CURRENT_TIMESTAMP
    FROM (
        SELECT duoc_pham_id, SUM(so_luong) AS tong_sl
        FROM ChiTietDonHang
        WHERE don_hang_id = p_don_hang_id
        GROUP BY duoc_pham_id
    ) sub
    WHERE dp.id = sub.duoc_pham_id;
END; $$;


ALTER PROCEDURE public.sp_hoan_thanh_don_hang(IN p_don_hang_id integer) OWNER TO postgres;

--
-- Name: sp_hoan_tra_thuoc(integer, integer, uuid[], text); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_hoan_tra_thuoc(IN p_don_hang_id integer, IN p_don_vi_nhan_id integer, IN p_mang_uid uuid[], IN p_ly_do text DEFAULT 'Khách hàng yêu cầu hoàn trả'::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    r             RECORD;
    v_count       INT;
    v_input_count INT;
    v_khach_hang_id INT;
    v_trang_thai  VARCHAR(50);
    v_phieu_id    INT;
    v_con_lai     INT;
BEGIN
    v_input_count := COALESCE(array_length(p_mang_uid, 1), 0);
    IF v_input_count = 0 THEN
        RAISE EXCEPTION 'Danh sách mã UID trống!';
    END IF;

    SELECT khach_hang_id, trang_thai_don
    INTO v_khach_hang_id, v_trang_thai
    FROM DonHang WHERE id = p_don_hang_id;

    IF v_khach_hang_id IS NULL THEN
        RAISE EXCEPTION 'Đơn hàng % không tồn tại!', p_don_hang_id;
    END IF;

    -- Cho phép trả tiếp nếu đã trả một phần
    IF v_trang_thai NOT IN ('ChoHoanTat', 'TraHangMotPhan') THEN
        RAISE EXCEPTION 'Chỉ được hoàn trả đơn hàng trong thời gian 7 ngày chờ hoàn tất. Trạng thái hiện tại: %',
            v_trang_thai;
    END IF;

    UPDATE HopThuoc
    SET don_hang_id        = NULL,
        don_vi_hien_tai_id = p_don_vi_nhan_id,
        trang_thai         = 'TrongKho'
    WHERE uid         = ANY(p_mang_uid)
      AND don_hang_id = p_don_hang_id;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> v_input_count THEN
        RAISE EXCEPTION 'Có %/% mã UID không thuộc đơn hàng %!',
            v_input_count - v_count, v_input_count, p_don_hang_id;
    END IF;

    -- Đếm hộp còn lại sau khi trả
    SELECT COUNT(*) INTO v_con_lai
    FROM HopThuoc WHERE don_hang_id = p_don_hang_id;

    SELECT unnest(p_mang_uid), p_don_vi_nhan_id, 'TraHang',
           'Hoàn trả từ đơn hàng #' || p_don_hang_id;

    FOR r IN (
        SELECT lt.duoc_pham_id, lt.quy_cach_id, COUNT(*) AS sl
        FROM HopThuoc ht
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        WHERE ht.uid = ANY(p_mang_uid)
        GROUP BY lt.duoc_pham_id, lt.quy_cach_id
    ) LOOP
        VALUES (p_don_vi_nhan_id, r.duoc_pham_id, r.quy_cach_id, r.sl)
        ON CONFLICT (don_vi_id, duoc_pham_id, quy_cach_id)
        DO UPDATE SET
            so_luong_ton  = TonKho.so_luong_ton + r.sl,
            ngay_cap_nhat = CURRENT_TIMESTAMP;
    END LOOP;

    UPDATE DuocPham dp
    SET so_luong_da_ban   = GREATEST(dp.so_luong_da_ban - sub.tong_sl, 0),
        ngay_cap_nhat_moi = CURRENT_TIMESTAMP
    FROM (
        SELECT lt.duoc_pham_id, COUNT(*) AS tong_sl
        FROM HopThuoc ht
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        WHERE ht.uid = ANY(p_mang_uid)
        GROUP BY lt.duoc_pham_id
    ) sub
    WHERE dp.id = sub.duoc_pham_id;

    -- Tạo phiếu trả hàng và ghi chi tiết mặt hàng được trả
    VALUES (p_don_hang_id, v_khach_hang_id, COALESCE(p_ly_do, 'Khách hàng yêu cầu hoàn trả'))
    RETURNING id INTO v_phieu_id;

    SELECT v_phieu_id, lt.duoc_pham_id, lt.quy_cach_id, COUNT(*)
    FROM HopThuoc ht
    JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
    WHERE ht.uid = ANY(p_mang_uid)
    GROUP BY lt.duoc_pham_id, lt.quy_cach_id;

    IF v_con_lai = 0 THEN
        UPDATE DonHang SET trang_thai_don = 'TraHang' WHERE id = p_don_hang_id;
    ELSE
        UPDATE DonHang SET trang_thai_don = 'TraHangMotPhan' WHERE id = p_don_hang_id;
    END IF;
END; $$;


ALTER PROCEDURE public.sp_hoan_tra_thuoc(IN p_don_hang_id integer, IN p_don_vi_nhan_id integer, IN p_mang_uid uuid[], IN p_ly_do text) OWNER TO postgres;

--
-- Name: sp_huy_don_hang_khach(integer, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_huy_don_hang_khach(IN p_don_hang_id integer, IN p_khach_hang_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE 
    v_trang_thai VARCHAR;
    v_diem_su_dung INT;
    v_ma_giam_gia VARCHAR;
    r RECORD;
BEGIN
    SELECT trang_thai_don, diem_su_dung, ma_giam_gia 
    INTO v_trang_thai, v_diem_su_dung, v_ma_giam_gia 
    FROM DonHang 
    WHERE id = p_don_hang_id AND khach_hang_id = p_khach_hang_id;
    
    IF v_trang_thai IS NULL THEN 
        RAISE EXCEPTION 'Đơn hàng không tồn tại!'; 
    END IF;

    IF v_trang_thai != 'ChoXacNhan' THEN 
        RAISE EXCEPTION 'Không thể hủy đơn hàng đang ở trạng thái: %', v_trang_thai; 
    END IF;

    UPDATE DonHang 
    SET trang_thai_don = 'DaHuy'
    WHERE id = p_don_hang_id;

    FOR r IN (
        SELECT 
            duoc_pham_id,
            quy_cach_id,
            don_vi_xuat_id,
            SUM(so_luong) as tong_so_luong 
        FROM ChiTietDonHang
        WHERE don_hang_id = p_don_hang_id
        GROUP BY duoc_pham_id, quy_cach_id, don_vi_xuat_id
    ) LOOP
        VALUES (r.don_vi_xuat_id, r.duoc_pham_id, r.quy_cach_id, r.tong_so_luong)
        ON CONFLICT (don_vi_id, duoc_pham_id, quy_cach_id)
        DO UPDATE SET 
            so_luong_ton = TonKho.so_luong_ton + r.tong_so_luong,
            ngay_cap_nhat = CURRENT_TIMESTAMP;
    END LOOP;

    IF v_diem_su_dung > 0 THEN
        UPDATE KhachHang 
        SET diem_tich_luy = diem_tich_luy + v_diem_su_dung
        WHERE id = p_khach_hang_id;
    END IF;

    IF v_ma_giam_gia IS NOT NULL AND v_ma_giam_gia != '' THEN
        UPDATE KhuyenMai 
        SET so_luong_da_dung = GREATEST(so_luong_da_dung - 1, 0)
        WHERE ma_code = v_ma_giam_gia;
    END IF;

END; $$;


ALTER PROCEDURE public.sp_huy_don_hang_khach(IN p_don_hang_id integer, IN p_khach_hang_id integer) OWNER TO postgres;

--
-- Name: sp_huy_don_qua_han(); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_huy_don_qua_han()
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Bước 1: Hoàn kho cho tất cả đơn quá hạn
    -- SET-based thay vì loop từng đơn → hiệu quả hơn khi batch
    SELECT
        ctd.don_vi_xuat_id,
        ctd.duoc_pham_id,
        ctd.quy_cach_id,
        SUM(ctd.so_luong)
    FROM ChiTietDonHang ctd
    JOIN DonHang dh ON ctd.don_hang_id = dh.id
    WHERE dh.trang_thai_don = 'ChoXacNhan'
      AND dh.ngay_dat_hang < CURRENT_TIMESTAMP - INTERVAL '3 days'
    GROUP BY ctd.don_vi_xuat_id, ctd.duoc_pham_id, ctd.quy_cach_id
    ON CONFLICT (don_vi_id, duoc_pham_id, quy_cach_id)
    DO UPDATE SET
        so_luong_ton = TonKho.so_luong_ton + EXCLUDED.so_luong_ton,
        ngay_cap_nhat = CURRENT_TIMESTAMP;

    -- Bước 2: Hoàn điểm tích lũy
    -- Trigger trg_auto_upgrade_tier sẽ tự tính lại hạng thành viên
    UPDATE KhachHang kh
    SET diem_tich_luy = kh.diem_tich_luy + sub.tong_diem
    FROM (
        SELECT khach_hang_id, SUM(diem_su_dung) AS tong_diem
        FROM DonHang
        WHERE trang_thai_don = 'ChoXacNhan'
          AND ngay_dat_hang < CURRENT_TIMESTAMP - INTERVAL '3 days'
          AND diem_su_dung > 0
        GROUP BY khach_hang_id
    ) sub
    WHERE kh.id = sub.khach_hang_id;

    -- Bước 3: Hoàn lượt dùng voucher
    UPDATE KhuyenMai km
    SET so_luong_da_dung = GREATEST(km.so_luong_da_dung - sub.so_luong_huy, 0)
    FROM (
        SELECT ma_giam_gia, COUNT(*) AS so_luong_huy
        FROM DonHang
        WHERE trang_thai_don = 'ChoXacNhan'
          AND ngay_dat_hang < CURRENT_TIMESTAMP - INTERVAL '3 days'
          AND ma_giam_gia IS NOT NULL
          AND TRIM(ma_giam_gia) != ''
        GROUP BY ma_giam_gia
    ) sub
    WHERE km.ma_code = sub.ma_giam_gia;

    -- Bước 4: Cập nhật trạng thái — PHẢI làm cuối cùng
    -- Nếu làm trước, WHERE ChoXacNhan ở bước 1-3 sẽ không khớp nữa
    UPDATE DonHang
    SET trang_thai_don = 'DaHuy'
    WHERE trang_thai_don = 'ChoXacNhan'
      AND ngay_dat_hang < CURRENT_TIMESTAMP - INTERVAL '3 days';

END; $$;


ALTER PROCEDURE public.sp_huy_don_qua_han() OWNER TO postgres;

--
-- Name: sp_kiem_ke_ton_kho(integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_kiem_ke_ton_kho(IN p_don_vi_id integer DEFAULT NULL::integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    cur_tk CURSOR (p_dv INT) FOR
        SELECT tk.don_vi_id, dv.ten_don_vi,
               tk.duoc_pham_id, dp.ten_thuoc,
               tk.quy_cach_id, qc.ten_don_vi AS quy_cach,
               tk.so_luong_ton
        FROM TonKho tk
        JOIN DonVi dv ON tk.don_vi_id = dv.id
        JOIN DuocPham dp ON tk.duoc_pham_id = dp.id
        JOIN QuyCachDongGoi qc ON tk.quy_cach_id = qc.id
        WHERE (p_dv IS NULL OR tk.don_vi_id = p_dv)
        ORDER BY tk.don_vi_id, dp.ten_thuoc;

    v_dv_id INT; v_ten_dv VARCHAR; v_dp_id INT; v_ten_thuoc VARCHAR;
    v_qc_id INT; v_quy_cach VARCHAR; v_ly_thuyet INT;
    v_thuc_te INT; v_lech INT;
    v_tong INT := 0; v_khop INT := 0; v_lech_cnt INT := 0;
BEGIN
    RAISE NOTICE 'KIỂM KÊ TỒN KHO%',
        CASE WHEN p_don_vi_id IS NOT NULL THEN ' (đơn vị #' || p_don_vi_id || ')' ELSE ' (toàn hệ thống)' END;
    OPEN cur_tk(p_don_vi_id);
    LOOP
        FETCH cur_tk INTO v_dv_id, v_ten_dv, v_dp_id, v_ten_thuoc, v_qc_id, v_quy_cach, v_ly_thuyet;
        EXIT WHEN NOT FOUND;
        v_tong := v_tong + 1;

        -- Đếm thực tế: số hộp UID đang 'TrongKho' tại đơn vị này, đúng thuốc + quy cách
        SELECT COUNT(ht.uid)
        INTO v_thuc_te
        FROM HopThuoc ht
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        WHERE ht.don_vi_hien_tai_id = v_dv_id
          AND lt.duoc_pham_id = v_dp_id
          AND lt.quy_cach_id = v_qc_id
          AND ht.trang_thai = 'TrongKho';

        v_lech := v_thuc_te - v_ly_thuyet;
        IF v_lech = 0 THEN
            v_khop := v_khop + 1;
            RAISE NOTICE 'Khớp: % | % (%): lý thuyết = thực tế = %',
                v_ten_dv, v_ten_thuoc, v_quy_cach, v_ly_thuyet;
        ELSE
            v_lech_cnt := v_lech_cnt + 1;
            RAISE NOTICE 'Lệch: % | % (%): lý thuyết %, thực tế %, lệch %',
                v_ten_dv, v_ten_thuoc, v_quy_cach, v_ly_thuyet, v_thuc_te, v_lech;
        END IF;
    END LOOP;
    CLOSE cur_tk;
    RAISE NOTICE 'Tổng: % dòng | Khớp: % | Lệch: %', v_tong, v_khop, v_lech_cnt;
END; $$;


ALTER PROCEDURE public.sp_kiem_ke_ton_kho(IN p_don_vi_id integer) OWNER TO postgres;

--
-- Name: sp_luan_chuyen_kho(integer, integer, uuid[]); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_luan_chuyen_kho(IN p_tu_don_vi_id integer, IN p_den_don_vi_id integer, IN p_mang_uid uuid[])
    LANGUAGE plpgsql
    AS $$
DECLARE
    r RECORD; v_count INT; v_input_count INT;
BEGIN
    v_input_count := COALESCE(array_length(p_mang_uid, 1), 0);
    IF v_input_count = 0 THEN
        RAISE EXCEPTION 'Danh sách mã UID trống!';
    END IF;

    UPDATE HopThuoc
    SET don_vi_hien_tai_id = p_den_don_vi_id,
        trang_thai = 'TrongKho'
    WHERE uid = ANY(p_mang_uid)
      AND don_vi_hien_tai_id = p_tu_don_vi_id
      AND trang_thai IN ('XuatXuong', 'TrongKho');

    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> v_input_count THEN
        RAISE EXCEPTION 'Lỗi: Có %/% mã không hợp lệ (sai vị trí hoặc trạng thái)!',
            (v_input_count - v_count), v_input_count;
    END IF;

    SELECT unnest(p_mang_uid), p_tu_don_vi_id, p_den_don_vi_id, 'XuatKho', 'Xuất kho luân chuyển đến đơn vị #' || p_den_don_vi_id;

    SELECT unnest(p_mang_uid), p_tu_don_vi_id, p_den_don_vi_id, 'NhapKho','Nhập kho từ đơn vị #' || p_tu_don_vi_id;

    FOR r IN (
        SELECT lt.duoc_pham_id, lt.quy_cach_id, COUNT(*) AS sl
        FROM HopThuoc ht
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        WHERE ht.uid = ANY(p_mang_uid)
        GROUP BY lt.duoc_pham_id, lt.quy_cach_id
    ) LOOP
        UPDATE TonKho
        SET so_luong_ton  = so_luong_ton - r.sl,
            ngay_cap_nhat = CURRENT_TIMESTAMP
        WHERE don_vi_id    = p_tu_don_vi_id
          AND duoc_pham_id = r.duoc_pham_id
          AND quy_cach_id  = r.quy_cach_id;

        VALUES (p_den_don_vi_id, r.duoc_pham_id, r.quy_cach_id, r.sl)
        ON CONFLICT (don_vi_id, duoc_pham_id, quy_cach_id) DO UPDATE
        SET so_luong_ton  = TonKho.so_luong_ton + r.sl,
            ngay_cap_nhat = CURRENT_TIMESTAMP;
    END LOOP;
END; $$;


ALTER PROCEDURE public.sp_luan_chuyen_kho(IN p_tu_don_vi_id integer, IN p_den_don_vi_id integer, IN p_mang_uid uuid[]) OWNER TO postgres;

--
-- Name: sp_luan_chuyen_kien_hang(character varying, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_luan_chuyen_kien_hang(IN p_ma_sscc character varying, IN p_den_don_vi_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_kien_id INT;
    v_tu_don_vi_id INT;
    r RECORD;
BEGIN
    SELECT id, don_vi_so_huu_id INTO v_kien_id, v_tu_don_vi_id
    FROM KienHang WHERE ma_sscc = p_ma_sscc;

    IF v_kien_id IS NULL THEN
        RAISE EXCEPTION 'Mã SSCC kiện hàng (%) không tồn tại!', p_ma_sscc;
    END IF;

    UPDATE KienHang
    SET don_vi_so_huu_id = p_den_don_vi_id
    WHERE id = v_kien_id;

    UPDATE HopThuoc
    SET don_vi_hien_tai_id = p_den_don_vi_id
    WHERE kien_hang_id = v_kien_id;

    SELECT uid, v_tu_don_vi_id, p_den_don_vi_id, 'XuatKho', 'Xuất kho: Luân chuyển theo kiện SSCC: ' || p_ma_sscc
    FROM HopThuoc WHERE kien_hang_id = v_kien_id;

    SELECT uid, v_tu_don_vi_id, p_den_don_vi_id, 'NhapKho', 'Nhập kho: Luân chuyển theo kiện SSCC: ' || p_ma_sscc
    FROM HopThuoc WHERE kien_hang_id = v_kien_id;

    FOR r IN (
        SELECT lt.duoc_pham_id, lt.quy_cach_id, COUNT(*) AS sl
        FROM HopThuoc ht
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        WHERE ht.kien_hang_id = v_kien_id
        GROUP BY lt.duoc_pham_id, lt.quy_cach_id
    ) LOOP
        UPDATE TonKho
        SET so_luong_ton  = so_luong_ton - r.sl,
            ngay_cap_nhat = CURRENT_TIMESTAMP
        WHERE don_vi_id    = v_tu_don_vi_id
          AND duoc_pham_id = r.duoc_pham_id
          AND quy_cach_id  = r.quy_cach_id;

        VALUES (p_den_don_vi_id, r.duoc_pham_id, r.quy_cach_id, r.sl)
        ON CONFLICT (don_vi_id, duoc_pham_id, quy_cach_id) DO UPDATE
        SET so_luong_ton  = TonKho.so_luong_ton + r.sl,
            ngay_cap_nhat = CURRENT_TIMESTAMP;
    END LOOP;
END; $$;


ALTER PROCEDURE public.sp_luan_chuyen_kien_hang(IN p_ma_sscc character varying, IN p_den_don_vi_id integer) OWNER TO postgres;

--
-- Name: sp_nhap_kho_lo_thuoc_moi(integer, integer, integer, text); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_nhap_kho_lo_thuoc_moi(IN p_lo_thuoc_id integer, IN p_don_vi_id integer, IN p_so_luong_hop integer, IN p_ghi_chu text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
DECLARE 
	v_duoc_pham_id INT; v_quy_cach_id INT; v_trang_thai_lo VARCHAR(50);
BEGIN
    SELECT duoc_pham_id, quy_cach_id, trang_thai
    INTO v_duoc_pham_id, v_quy_cach_id, v_trang_thai_lo
    FROM LoThuoc
    WHERE id = p_lo_thuoc_id;

    IF v_duoc_pham_id IS NULL THEN
        RAISE EXCEPTION 'Lô thuốc ID % không tồn tại!', p_lo_thuoc_id;
    END IF;

    IF v_trang_thai_lo != 'HopLe' THEN
        RAISE EXCEPTION 'Lô thuốc không hợp lệ để nhập. Trạng thái hiện tại: %', v_trang_thai_lo;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM QuyCachDongGoi
        WHERE id = v_quy_cach_id AND duoc_pham_id = v_duoc_pham_id
    ) THEN
        RAISE EXCEPTION 'Quy cách đóng gói % không tồn tại cho thuốc %', v_quy_cach_id, v_duoc_pham_id;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM DonVi WHERE id = p_don_vi_id) THEN
        RAISE EXCEPTION 'Kho (ID: %) không tồn tại!', p_don_vi_id;
    END IF;

    VALUES (p_don_vi_id, v_duoc_pham_id, v_quy_cach_id, p_so_luong_hop)
    ON CONFLICT (don_vi_id, duoc_pham_id, quy_cach_id) DO UPDATE
    SET so_luong_ton  = TonKho.so_luong_ton + p_so_luong_hop,
        ngay_cap_nhat = CURRENT_TIMESTAMP;

    CALL sp_Generate_Pharma_UIDs(p_lo_thuoc_id, p_so_luong_hop, p_don_vi_id);

    WITH hop_vua_nhap AS (
        UPDATE HopThuoc
        SET trang_thai = 'TrongKho'
        WHERE lo_thuoc_id      = p_lo_thuoc_id
          AND don_vi_hien_tai_id = p_don_vi_id
          AND trang_thai       = 'XuatXuong'
        RETURNING uid
    )
    SELECT uid, p_don_vi_id, 'NhapKho', 'Nhập kho lô ' || p_lo_thuoc_id || ' - ' || COALESCE(p_ghi_chu, 'Nhập kho')
    FROM hop_vua_nhap;

    RAISE NOTICE 'Nhập kho thành công: % hộp từ lô thuốc ID %', p_so_luong_hop, p_lo_thuoc_id;
END; $$;


ALTER PROCEDURE public.sp_nhap_kho_lo_thuoc_moi(IN p_lo_thuoc_id integer, IN p_don_vi_id integer, IN p_so_luong_hop integer, IN p_ghi_chu text) OWNER TO postgres;

--
-- Name: sp_phan_bo_xuat_kho_fefo(integer, integer, integer, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_phan_bo_xuat_kho_fefo(IN p_duoc_pham_id integer, IN p_quy_cach_id integer, IN p_don_vi_id integer, IN p_can integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
   	cur_lo CURSOR FOR
		SELECT lt.id,lt.so_lo, lt.han_su_dung, COUNT(ht.uid) AS so_hop_co
		FROM LoThuoc lt
		JOIN HopThuoc ht ON ht.lo_thuoc_id = lt.id
		WHERE lt.duoc_pham_id = p_duoc_pham_id
		  AND lt.quy_cach_id = p_quy_cach_id
		  AND lt.trang_thai = 'HopLe'
		  AND ht.don_vi_hien_tai_id = p_don_vi_id
		  AND ht.trang_thai = 'TrongKho'
		GROUP BY lt.id, lt.so_lo, lt.han_su_dung
		ORDER BY lt.han_su_dung;
	
    v_lo_id INT; v_so_lo VARCHAR; v_hsd DATE;
    v_co INT; v_lay INT; v_con_lai INT;
BEGIN
    RAISE NOTICE 'FEFO: thuốc %, quy cách %, kho %, cần % hộp',
        p_duoc_pham_id, p_quy_cach_id, p_don_vi_id, p_can;
    v_con_lai := p_can;
    OPEN cur_lo;
    LOOP
        FETCH cur_lo INTO v_lo_id, v_so_lo, v_hsd, v_co;
        EXIT WHEN NOT FOUND;
        EXIT WHEN v_con_lai <= 0;
        v_lay := LEAST(v_co, v_con_lai);
        v_con_lai := v_con_lai - v_lay;
        RAISE NOTICE
            'Lô % (HSD %) - Có % hộp - Lấy % - Còn cần %', v_so_lo, v_hsd, v_co, v_lay, v_con_lai;
    END LOOP;
    CLOSE cur_lo;
    IF v_con_lai > 0 THEN
        RAISE NOTICE 'THIẾU HÀNG: còn thiếu % hộp', v_con_lai;
    ELSE
        RAISE NOTICE 'ĐÃ PHÂN BỔ ĐỦ % hộp', p_can;
    END IF;
END; $$;


ALTER PROCEDURE public.sp_phan_bo_xuat_kho_fefo(IN p_duoc_pham_id integer, IN p_quy_cach_id integer, IN p_don_vi_id integer, IN p_can integer) OWNER TO postgres;

--
-- Name: sp_phan_tich_abc_ton_kho(integer, numeric, numeric); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_phan_tich_abc_ton_kho(IN p_don_vi_id integer DEFAULT NULL::integer, IN p_nguong_a numeric DEFAULT 80, IN p_nguong_b numeric DEFAULT 95)
    LANGUAGE plpgsql
    AS $$
DECLARE
    cur_sp CURSOR FOR
        SELECT dp.ten_thuoc, SUM(tk.so_luong_ton * qc.gia_ban) AS gia_tri
        FROM TonKho tk
        JOIN DuocPham dp ON tk.duoc_pham_id = dp.id
        JOIN QuyCachDongGoi qc ON tk.quy_cach_id = qc.id
        WHERE (p_don_vi_id IS NULL OR tk.don_vi_id = p_don_vi_id)
        GROUP BY dp.id, dp.ten_thuoc
        HAVING SUM(tk.so_luong_ton * qc.gia_ban) > 0
        ORDER BY gia_tri DESC;
    v_ten VARCHAR;
    v_gia_tri DECIMAL;
    v_tong DECIMAL;
    v_luy_ke DECIMAL := 0;
    v_pct NUMERIC;
    v_hang CHAR(1);
    v_a INT := 0; v_b INT := 0; v_c INT := 0;
BEGIN
    RAISE NOTICE 'PHÂN TÍCH ABC TỒN KHO (kho: %) ==',
        COALESCE(p_don_vi_id::TEXT, 'tất cả');
    SELECT SUM(tk.so_luong_ton * qc.gia_ban)
    INTO v_tong
    FROM TonKho tk
    JOIN QuyCachDongGoi qc ON tk.quy_cach_id = qc.id
    WHERE (p_don_vi_id IS NULL OR tk.don_vi_id = p_don_vi_id);

    IF COALESCE(v_tong, 0) = 0 THEN
        RAISE NOTICE 'Không có tồn kho để phân tích.';
        RETURN;
    END IF;

    OPEN cur_sp;
    LOOP
        FETCH cur_sp INTO v_ten, v_gia_tri;
        EXIT WHEN NOT FOUND;
        v_luy_ke := v_luy_ke + v_gia_tri;
        v_pct := ROUND(v_luy_ke / v_tong * 100, 1);
        v_hang := CASE
            WHEN v_pct <= p_nguong_a THEN 'A'
            WHEN v_pct <= p_nguong_b THEN 'B'
            ELSE 'C'
        END;
        IF v_hang = 'A' THEN v_a := v_a + 1;
        ELSIF v_hang = 'B' THEN v_b := v_b + 1;
        ELSE v_c := v_c + 1;
        END IF;
        RAISE NOTICE '[%] % | Giá trị: % | Lũy kế: % %%',
            v_hang, v_ten, v_gia_tri, v_pct;
    END LOOP;
    CLOSE cur_sp;
    RAISE NOTICE 'Hạng A=% sp, B=% sp, C=% sp.', v_a, v_b, v_c;
END; $$;


ALTER PROCEDURE public.sp_phan_tich_abc_ton_kho(IN p_don_vi_id integer, IN p_nguong_a numeric, IN p_nguong_b numeric) OWNER TO postgres;

--
-- Name: sp_phat_hien_qr_bat_thuong(double precision, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_phat_hien_qr_bat_thuong(IN p_nguong_kmh double precision DEFAULT 1000, IN p_so_ngay integer DEFAULT NULL::integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    cur_quet CURSOR FOR
        SELECT hop_thuoc_uid, thoi_gian_quet, toa_do_lat, toa_do_lng
        FROM NhatKyXacThuc
        WHERE toa_do_lat IS NOT NULL AND toa_do_lng IS NOT NULL
          AND (p_so_ngay IS NULL
               OR thoi_gian_quet > CURRENT_TIMESTAMP - (p_so_ngay || ' days')::INTERVAL)
        ORDER BY hop_thuoc_uid, thoi_gian_quet;
    v_uid UUID;
    v_time TIMESTAMP;
    v_lat DECIMAL;
    v_lng DECIMAL;
    v_uid_prev UUID := NULL;
    v_time_prev TIMESTAMP;
    v_lat_prev DECIMAL;
    v_lng_prev DECIMAL;
    v_dist FLOAT;
    v_hours FLOAT;
    v_speed FLOAT;
    v_nghi_van INT := 0;
BEGIN
    RAISE NOTICE '== PHÁT HIỆN QR BẤT THƯỜNG (ngưỡng % km/h) ==', p_nguong_kmh;
    OPEN cur_quet;
    LOOP
        FETCH cur_quet INTO v_uid, v_time, v_lat, v_lng;
        EXIT WHEN NOT FOUND;
        IF v_uid = v_uid_prev THEN
            v_dist := fn_tinh_khoang_cach_km(v_lat_prev, v_lng_prev, v_lat, v_lng);
            v_hours := EXTRACT(EPOCH FROM (v_time - v_time_prev)) / 3600.0;
            IF v_hours > 0 THEN
                v_speed := v_dist / v_hours;
                IF v_speed > p_nguong_kmh THEN
                    v_nghi_van := v_nghi_van + 1;
                    RAISE NOTICE 'Hộp %: % km trong % giờ = % km/h → NGHI VẤN',
                        v_uid,
                        ROUND(v_dist::NUMERIC, 1),
                        ROUND(v_hours::NUMERIC, 2),
                        ROUND(v_speed::NUMERIC, 0);
                END IF;
            END IF;
        END IF;
        v_uid_prev := v_uid;
        v_time_prev := v_time;
        v_lat_prev := v_lat;
        v_lng_prev := v_lng;
    END LOOP;
    CLOSE cur_quet;
    RAISE NOTICE 'Phát hiện % lần di chuyển bất thường.', v_nghi_van;
END; $$;


ALTER PROCEDURE public.sp_phat_hien_qr_bat_thuong(IN p_nguong_kmh double precision, IN p_so_ngay integer) OWNER TO postgres;

--
-- Name: sp_tao_don_hang_tu_gio(integer, integer, text, character varying, character varying, integer, numeric, integer, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_tao_don_hang_tu_gio(IN p_khach_hang_id integer, IN p_don_vi_xuat_id integer, IN p_dia_chi_giao text, IN p_phuong_thuc_tt character varying, IN p_ma_giam_gia character varying DEFAULT NULL::character varying, IN p_diem_su_dung integer DEFAULT 0, IN p_phi_ship numeric DEFAULT 30000, IN p_toa_thuoc_id integer DEFAULT NULL::integer, INOUT p_don_hang_id integer DEFAULT NULL::integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tong_tien_hang DECIMAL := 0; v_tien_giam_tu_diem DECIMAL := 0; v_tien_giam_tu_voucher DECIMAL := 0; v_tong_tien_thanh_toan DECIMAL := 0;
    v_diem_hien_co INT; v_voucher RECORD; v_co_thuoc_ke_don BOOLEAN := FALSE;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM KhachHang WHERE id = p_khach_hang_id) THEN
        RAISE EXCEPTION 'Khách hàng không tồn tại';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM DonVi WHERE id = p_don_vi_xuat_id) THEN
        RAISE EXCEPTION 'Kho xuất không tồn tại';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM ChiTietGioHang WHERE khach_hang_id = p_khach_hang_id) THEN
        RAISE EXCEPTION 'Giỏ hàng trống';
    END IF;

	IF EXISTS (
        SELECT 1
        FROM ChiTietGioHang ctg
        JOIN DuocPham dp ON ctg.duoc_pham_id = dp.id
        WHERE ctg.khach_hang_id = p_khach_hang_id
          AND (dp.trang_thai = FALSE OR dp.trang_thai_duyet != 'DaDuyet')
    ) THEN
        RAISE EXCEPTION 'Giỏ hàng chứa sản phẩm đã bị ngừng kinh doanh hoặc chưa được duyệt. Vui lòng kiểm tra và cập nhật giỏ hàng.';
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM ChiTietGioHang ctg
        JOIN DuocPham dp ON ctg.duoc_pham_id = dp.id
        WHERE ctg.khach_hang_id = p_khach_hang_id
          AND dp.la_thuoc_ke_don = TRUE
    ) INTO v_co_thuoc_ke_don;

    IF v_co_thuoc_ke_don THEN
        IF p_toa_thuoc_id IS NULL THEN
            RAISE EXCEPTION 'Giỏ hàng có thuốc kê đơn. Vui lòng cung cấp mã toa thuốc.';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM ToaThuoc
            WHERE id             = p_toa_thuoc_id
              AND khach_hang_id  = p_khach_hang_id
              AND trang_thai_duyet = 'HopLe'
              AND don_hang_id    IS NULL
        ) THEN
            RAISE EXCEPTION 'Toa thuốc không hợp lệ hoặc đã được sử dụng.';
        END IF;
    END IF;

    IF p_diem_su_dung > 0 THEN
        SELECT diem_tich_luy INTO v_diem_hien_co
        FROM KhachHang WHERE id = p_khach_hang_id;

        IF v_diem_hien_co < p_diem_su_dung THEN
            RAISE EXCEPTION 'Điểm tích lũy không đủ. Hiện có: %, Sử dụng: %',
                v_diem_hien_co, p_diem_su_dung;
        END IF;
        v_tien_giam_tu_diem := p_diem_su_dung * 100;
    END IF;

    SELECT COALESCE(SUM(qc.gia_ban * ctg.so_luong), 0)
	INTO v_tong_tien_hang
	FROM (
	    SELECT quy_cach_id, so_luong
	    FROM ChiTietGioHang
	    WHERE khach_hang_id = p_khach_hang_id
	    FOR UPDATE
	) ctg
	JOIN QuyCachDongGoi qc ON ctg.quy_cach_id = qc.id;

    IF p_ma_giam_gia IS NOT NULL AND TRIM(p_ma_giam_gia) != '' THEN
        SELECT * INTO v_voucher
        FROM KhuyenMai
        WHERE ma_code = TRIM(p_ma_giam_gia)
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Mã giảm giá không tồn tại';
        END IF;
        IF NOT (CURRENT_TIMESTAMP BETWEEN v_voucher.ngay_bat_dau AND v_voucher.ngay_ket_thuc) THEN
            RAISE EXCEPTION 'Mã giảm giá đã hết hạn';
        END IF;
        IF v_voucher.so_luong_gioi_han IS NOT NULL
           AND v_voucher.so_luong_da_dung >= v_voucher.so_luong_gioi_han THEN
            RAISE EXCEPTION 'Mã giảm giá đã hết lượt sử dụng';
        END IF;
        IF (v_tong_tien_hang + p_phi_ship) < v_voucher.don_hang_toi_thieu THEN
            RAISE EXCEPTION 'Đơn hàng phải từ % để áp dụng mã này', v_voucher.don_hang_toi_thieu;
        END IF;

        IF v_voucher.loai_giam_gia = 'PhanTram' THEN
            v_tien_giam_tu_voucher := ROUND((v_tong_tien_hang + p_phi_ship) * (v_voucher.gia_tri / 100), 0);
        ELSIF v_voucher.loai_giam_gia = 'TienMat' THEN
            v_tien_giam_tu_voucher := v_voucher.gia_tri;
        ELSIF v_voucher.loai_giam_gia = 'FreeShip' THEN
            v_tien_giam_tu_voucher := p_phi_ship;
        END IF;
    END IF;

    v_tong_tien_thanh_toan := GREATEST(
        v_tong_tien_hang + p_phi_ship - v_tien_giam_tu_voucher - v_tien_giam_tu_diem,
        0
    );

                         phuong_thuc_thanh_toan, ma_giam_gia, diem_su_dung,
                         tien_giam_tu_diem, tien_giam_tu_voucher)
    VALUES (p_khach_hang_id, v_tong_tien_thanh_toan, p_phi_ship, p_dia_chi_giao,
            p_phuong_thuc_tt, NULLIF(TRIM(p_ma_giam_gia), ''), p_diem_su_dung,
            v_tien_giam_tu_diem, v_tien_giam_tu_voucher)
    RETURNING id INTO p_don_hang_id;

                                don_gia, don_vi_xuat_id, gia_goc_luc_mua, phan_tram_giam_luc_mua)
    SELECT p_don_hang_id, ctg.duoc_pham_id, ctg.quy_cach_id, ctg.so_luong,
           qc.gia_ban, p_don_vi_xuat_id, qc.gia_goc, qc.phan_tram_giam
    FROM ChiTietGioHang ctg
    JOIN QuyCachDongGoi qc ON ctg.quy_cach_id = qc.id
    WHERE ctg.khach_hang_id = p_khach_hang_id;

    DELETE FROM ChiTietGioHang WHERE khach_hang_id = p_khach_hang_id;

    IF v_co_thuoc_ke_don AND p_toa_thuoc_id IS NOT NULL THEN
        UPDATE ToaThuoc SET don_hang_id = p_don_hang_id WHERE id = p_toa_thuoc_id;
    END IF;

    IF p_diem_su_dung > 0 THEN
        UPDATE KhachHang
        SET diem_tich_luy = diem_tich_luy - p_diem_su_dung
        WHERE id = p_khach_hang_id;
    END IF;

    IF p_ma_giam_gia IS NOT NULL AND TRIM(p_ma_giam_gia) != '' THEN
        UPDATE KhuyenMai
        SET so_luong_da_dung = so_luong_da_dung + 1
        WHERE ma_code = TRIM(p_ma_giam_gia);
    END IF;

END; $$;


ALTER PROCEDURE public.sp_tao_don_hang_tu_gio(IN p_khach_hang_id integer, IN p_don_vi_xuat_id integer, IN p_dia_chi_giao text, IN p_phuong_thuc_tt character varying, IN p_ma_giam_gia character varying, IN p_diem_su_dung integer, IN p_phi_ship numeric, IN p_toa_thuoc_id integer, INOUT p_don_hang_id integer) OWNER TO postgres;

--
-- Name: sp_thu_hoi_hang_loat(integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_thu_hoi_hang_loat(IN p_nha_san_xuat_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    cur_lo CURSOR FOR
        SELECT lt.id, lt.so_lo, dp.ten_thuoc
        FROM LoThuoc lt
        JOIN DuocPham dp ON lt.duoc_pham_id = dp.id
        WHERE dp.don_vi_san_xuat_id = p_nha_san_xuat_id
          AND lt.trang_thai = 'HopLe'
        ORDER BY lt.id;
    v_lo_id INT;
    v_so_lo VARCHAR;
    v_ten VARCHAR;
    v_ok INT := 0;
    v_fail INT := 0;
BEGIN
    RAISE NOTICE 'Thu hồi hàng loạt (NSX #%)', p_nha_san_xuat_id;
    OPEN cur_lo;
    LOOP
        FETCH cur_lo INTO v_lo_id, v_so_lo, v_ten;
        EXIT WHEN NOT FOUND;
        BEGIN
            CALL sp_thu_hoi_lo_thuoc(v_lo_id);
            v_ok := v_ok + 1;
            RAISE NOTICE 'Đã thu hồi lô % (%)', v_so_lo, v_ten;
        EXCEPTION WHEN OTHERS THEN
            v_fail := v_fail + 1;
            RAISE NOTICE 'Lỗi thu hồi lô % (%): %', v_so_lo, v_ten, SQLERRM;
        END;
    END LOOP;
    CLOSE cur_lo;
    RAISE NOTICE 'Thành công % lô, lỗi % lô.', v_ok, v_fail;
END; $$;


ALTER PROCEDURE public.sp_thu_hoi_hang_loat(IN p_nha_san_xuat_id integer) OWNER TO postgres;

--
-- Name: sp_thu_hoi_lo_thuoc(integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_thu_hoi_lo_thuoc(IN p_lo_thuoc_id integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE LoThuoc SET trang_thai = 'ThuHoi' WHERE id = p_lo_thuoc_id;

    UPDATE HopThuoc
    SET trang_thai = 'ThuHoi'
    WHERE lo_thuoc_id = p_lo_thuoc_id AND trang_thai != 'HuyBo';

    UPDATE TonKho tk
    SET so_luong_ton = GREATEST(tk.so_luong_ton - sub.sl, 0),
        ngay_cap_nhat = CURRENT_TIMESTAMP
    FROM (
        SELECT
            ht.don_vi_hien_tai_id AS don_vi_id,
            lt.duoc_pham_id,
            lt.quy_cach_id,
            COUNT(*) AS sl
        FROM HopThuoc ht
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        WHERE ht.lo_thuoc_id = p_lo_thuoc_id
          AND ht.trang_thai = 'ThuHoi'
          AND lt.trang_thai = 'ThuHoi'
          AND (
              SELECT lsp.loai_giao_dich
              FROM LichSuPhanPhoi lsp
              WHERE lsp.hop_thuoc_uid = ht.uid
              ORDER BY lsp.thoi_gian DESC, lsp.id DESC
              LIMIT 1
          ) IS DISTINCT FROM 'GiaoChoKhach'
        GROUP BY ht.don_vi_hien_tai_id, lt.duoc_pham_id, lt.quy_cach_id
    ) sub
    WHERE tk.don_vi_id = sub.don_vi_id
      AND tk.duoc_pham_id = sub.duoc_pham_id
      AND tk.quy_cach_id = sub.quy_cach_id;

    SELECT uid, 'ThuHoi'
    FROM HopThuoc
    WHERE lo_thuoc_id = p_lo_thuoc_id AND trang_thai = 'ThuHoi';
END; $$;


ALTER PROCEDURE public.sp_thu_hoi_lo_thuoc(IN p_lo_thuoc_id integer) OWNER TO postgres;

--
-- Name: sp_tu_choi_toa_thuoc_qua_han(integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_tu_choi_toa_thuoc_qua_han(IN p_so_ngay integer DEFAULT 14)
    LANGUAGE plpgsql
    AS $$
DECLARE
    cur_toa CURSOR FOR
        SELECT id, khach_hang_id, don_hang_id, ten_bac_si, ten_benh_vien, ngay_tao
        FROM ToaThuoc
        WHERE trang_thai_duyet = 'ChoDuyet'
          AND ngay_tao < CURRENT_TIMESTAMP - (p_so_ngay || ' days')::INTERVAL
        ORDER BY ngay_tao
        FOR UPDATE;

    v_id INT; v_kh_id INT; v_don_id INT;
    v_bac_si VARCHAR; v_benh_vien VARCHAR; v_ngay_tao TIMESTAMP;
    v_ngay_cho INT; v_so_tu_choi INT := 0; v_tong INT := 0;
BEGIN
    RAISE NOTICE 'Tự động từ chối toa thuốc chờ duyệt quá % ngày', p_so_ngay;
    OPEN cur_toa;
    LOOP
        FETCH cur_toa INTO v_id, v_kh_id, v_don_id, v_bac_si, v_benh_vien, v_ngay_tao;
        EXIT WHEN NOT FOUND;
        v_tong := v_tong + 1;
        v_ngay_cho := EXTRACT(DAY FROM CURRENT_TIMESTAMP - v_ngay_tao)::INT;
        UPDATE ToaThuoc SET trang_thai_duyet = 'TuChoi' WHERE CURRENT OF cur_toa;
        v_so_tu_choi := v_so_tu_choi + 1;
        UPDATE ToaThuoc SET trang_thai_duyet = 'TuChoi' WHERE CURRENT OF cur_toa;
        v_so_tu_choi := v_so_tu_choi + 1;
        RAISE NOTICE 'Toa #% - KH % - Đơn #% - BS: % (%) - Nộp: % - Đã chờ % ngày -> TỪ CHỐI',
            v_id, v_kh_id, v_don_id, v_bac_si, v_benh_vien, v_ngay_tao, v_ngay_cho;
    END LOOP;
    CLOSE cur_toa;
    RAISE NOTICE 'Đã từ chối %/% toa thuốc chờ duyệt quá % ngày.', v_so_tu_choi, v_tong, p_so_ngay;
END; $$;


ALTER PROCEDURE public.sp_tu_choi_toa_thuoc_qua_han(IN p_so_ngay integer) OWNER TO postgres;

--
-- Name: sp_xac_nhan_hoan_tat_sau_7_ngay(); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_xac_nhan_hoan_tat_sau_7_ngay()
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Tính 1 lần, dùng cho cả 2 UPDATE bên dưới
    CREATE TEMP TABLE t_du_dieu_kien AS
    SELECT
        dh.id           AS don_hang_id,
        dh.khach_hang_id,
        FLOOR(dh.tong_tien / 1000)::INT AS diem
    FROM DonHang dh
    WHERE dh.trang_thai_don = 'ChoHoanTat'
      AND (
          SELECT MAX(lsp.thoi_gian)
          FROM LichSuPhanPhoi lsp
          JOIN HopThuoc ht ON ht.uid = lsp.hop_thuoc_uid
          WHERE ht.don_hang_id       = dh.id
            AND lsp.loai_giao_dich   = 'GiaoChoKhach'
      ) <= CURRENT_TIMESTAMP - INTERVAL '7 days';

    UPDATE KhachHang kh
	SET diem_tich_luy = kh.diem_tich_luy + t.diem,
	    diem_tich_luy_tong = kh.diem_tich_luy_tong + t.diem
	FROM t_du_dieu_kien t
	WHERE kh.id = t.khach_hang_id;

    UPDATE DonHang
    SET trang_thai_don = 'HoanThanh'
    WHERE id IN (SELECT don_hang_id FROM t_du_dieu_kien);

    DROP TABLE t_du_dieu_kien;
END;
$$;


ALTER PROCEDURE public.sp_xac_nhan_hoan_tat_sau_7_ngay() OWNER TO postgres;

--
-- Name: sp_xuat_giao_don_hang(integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_xuat_giao_don_hang(IN p_don_hang_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_trang_thai VARCHAR;
BEGIN
    SELECT trang_thai_don INTO v_trang_thai
    FROM DonHang WHERE id = p_don_hang_id;

    IF v_trang_thai IS NULL THEN
        RAISE EXCEPTION 'Đơn hàng không tồn tại!';
    END IF;

    IF v_trang_thai != 'DaDongGoi' THEN
        RAISE EXCEPTION 'Chỉ xuất giao khi đơn đã đóng gói xong. Hiện tại: %', v_trang_thai;
    END IF;

    UPDATE DonHang SET trang_thai_don = 'DangGiao' WHERE id = p_don_hang_id;

    UPDATE HopThuoc
    SET trang_thai = 'DangGiao'
    WHERE don_hang_id = p_don_hang_id AND trang_thai = 'DaDongGoi';

	SELECT uid, don_vi_hien_tai_id, 'GiaoChoKhach', 'Bàn giao cho đơn vị vận chuyển'
	FROM HopThuoc
	WHERE don_hang_id = p_don_hang_id AND trang_thai = 'DangGiao';

END; $$;


ALTER PROCEDURE public.sp_xuat_giao_don_hang(IN p_don_hang_id integer) OWNER TO postgres;

--
-- Name: sp_xuat_huy_thuoc(integer, uuid[], text); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_xuat_huy_thuoc(IN p_don_vi_id integer, IN p_mang_uid uuid[], IN p_ly_do text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    r             RECORD;
    v_count       INT;
    v_input_count INT;
BEGIN
    v_input_count := COALESCE(array_length(p_mang_uid, 1), 0);
    IF v_input_count = 0 THEN
        RAISE EXCEPTION 'Danh sách mã UID trống!';
    END IF;

    -- Trừ TonKho TRƯỚC khi update trang_thai (đọc trang_thai gốc)
    -- Chỉ trừ hộp TrongKho / XuatXuong — hộp ThuHoi đã được xử lý
    -- bởi sp_thu_hoi_lo_thuoc hoặc đã không còn trong TonKho
    FOR r IN (
        SELECT lt.duoc_pham_id, lt.quy_cach_id, COUNT(*) AS sl
        FROM HopThuoc ht
        JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id
        WHERE ht.uid                  = ANY(p_mang_uid)
          AND ht.don_vi_hien_tai_id   = p_don_vi_id
          AND ht.trang_thai           IN ('TrongKho', 'XuatXuong')
        GROUP BY lt.duoc_pham_id, lt.quy_cach_id
    ) LOOP
        UPDATE TonKho
        SET so_luong_ton  = so_luong_ton - r.sl,
            ngay_cap_nhat = CURRENT_TIMESTAMP
        WHERE don_vi_id    = p_don_vi_id
          AND duoc_pham_id = r.duoc_pham_id
          AND quy_cach_id  = r.quy_cach_id;
    END LOOP;

    -- Đánh dấu HuyBo (bao gồm cả hộp ThuHoi trả về từ khách)
    UPDATE HopThuoc
    SET trang_thai = 'HuyBo'
    WHERE uid                = ANY(p_mang_uid)
      AND don_vi_hien_tai_id = p_don_vi_id
      AND trang_thai         IN ('TrongKho', 'XuatXuong', 'ThuHoi');

    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> v_input_count THEN
        RAISE EXCEPTION
            'Lỗi: %/% hộp thuốc không hợp lệ để xuất hủy (sai đơn vị, sai trạng thái, hoặc không tồn tại)!',
            (v_input_count - v_count), v_input_count;
    END IF;

    SELECT unnest(p_mang_uid), p_don_vi_id, 'XuatHuy', p_ly_do;
END;
$$;


ALTER PROCEDURE public.sp_xuat_huy_thuoc(IN p_don_vi_id integer, IN p_mang_uid uuid[], IN p_ly_do text) OWNER TO postgres;

--
-- Name: trg_auto_deduct_inventory_from_order(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_auto_deduct_inventory_from_order() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ton_hien_tai INT;
BEGIN
    SELECT so_luong_ton INTO v_ton_hien_tai
    FROM TonKho
    WHERE don_vi_id = NEW.don_vi_xuat_id
      AND duoc_pham_id = NEW.duoc_pham_id
      AND quy_cach_id = NEW.quy_cach_id
    FOR UPDATE;

    IF v_ton_hien_tai IS NULL THEN
        RAISE EXCEPTION 'Kho (ID: %) không có sản phẩm (ID: %, quy cách: %)',
            NEW.don_vi_xuat_id, NEW.duoc_pham_id, NEW.quy_cach_id;
    END IF;

    IF v_ton_hien_tai < NEW.so_luong THEN
        RAISE EXCEPTION 'Tồn kho không đủ tại kho ID: %. Sản phẩm (ID: %, quy cách: %). Cần: %, Còn: %',
            NEW.don_vi_xuat_id, NEW.duoc_pham_id, NEW.quy_cach_id,
            NEW.so_luong, v_ton_hien_tai;
    END IF;

    UPDATE TonKho
    SET so_luong_ton = so_luong_ton - NEW.so_luong
    WHERE don_vi_id = NEW.don_vi_xuat_id
      AND duoc_pham_id = NEW.duoc_pham_id
      AND quy_cach_id = NEW.quy_cach_id;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_auto_deduct_inventory_from_order() OWNER TO postgres;

--
-- Name: trg_auto_upgrade_tier(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_auto_upgrade_tier() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.diem_tich_luy_tong IS DISTINCT FROM OLD.diem_tich_luy_tong THEN
        IF NEW.diem_tich_luy_tong >= 10000 THEN 
            NEW.hang_thanh_vien := 'Kim Cương';
        ELSIF NEW.diem_tich_luy_tong >= 5000 THEN 
            NEW.hang_thanh_vien := 'Bạch Kim';
        ELSIF NEW.diem_tich_luy_tong >= 2000 THEN 
            NEW.hang_thanh_vien := 'Vàng';
        ELSIF NEW.diem_tich_luy_tong >= 500 THEN 
            NEW.hang_thanh_vien := 'Bạc';
        END IF;
    END IF;
    RETURN NEW; 
END; 
$$;


ALTER FUNCTION public.trg_auto_upgrade_tier() OWNER TO postgres;

--
-- Name: trg_block_fake_uid(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_block_fake_uid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_risk_score INT;
BEGIN
    v_risk_score := fn_check_qr_risk_score(
        p_uid => NEW.hop_thuoc_uid,
        p_new_lat => NEW.toa_do_lat,
        p_new_lng => NEW.toa_do_lng,
        p_new_time => NEW.thoi_gian_quet
    );

    IF v_risk_score = 100 THEN
        NEW.trang_thai_canh_bao := TRUE;
        UPDATE HopThuoc SET trang_thai = 'CanhBaoGia' WHERE uid = NEW.hop_thuoc_uid;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_block_fake_uid() OWNER TO postgres;

--
-- Name: trg_handle_discount_logic(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_handle_discount_logic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.gia_goc > 0 AND NEW.phan_tram_giam > 0 THEN
        NEW.gia_ban := NEW.gia_goc * (1 - NEW.phan_tram_giam::DECIMAL / 100);
    ELSIF NEW.phan_tram_giam = 0 AND NEW.gia_goc > 0 THEN
        NEW.gia_ban := NEW.gia_goc;
    ELSIF NEW.gia_ban > 0 AND NEW.phan_tram_giam > 0 AND NEW.phan_tram_giam < 100 THEN
        NEW.gia_goc := NEW.gia_ban / (1 - NEW.phan_tram_giam::DECIMAL / 100);
    END IF;

    RETURN NEW;
END; $$;


ALTER FUNCTION public.trg_handle_discount_logic() OWNER TO postgres;

--
-- Name: trg_prevent_expired_delivery(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_prevent_expired_delivery() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_hsd DATE; BEGIN IF NEW.loai_giao_dich = 'GiaoChoKhach' THEN SELECT lt.han_su_dung INTO v_hsd FROM HopThuoc ht JOIN LoThuoc lt ON ht.lo_thuoc_id = lt.id WHERE ht.uid = NEW.hop_thuoc_uid; IF v_hsd < CURRENT_DATE THEN RAISE EXCEPTION 'Thuốc đã hết hạn, không được xuất kho!'; END IF; END IF; RETURN NEW; END; $$;


ALTER FUNCTION public.trg_prevent_expired_delivery() OWNER TO postgres;

--
-- Name: trg_tru_ton_kho(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_tru_ton_kho() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE 
    v_ton_kho_hien_tai INT;
BEGIN 
    -- 1. Lấy số lượng tồn hiện tại của ĐÚNG kho được chỉ định
    SELECT so_luong_ton INTO v_ton_kho_hien_tai
    FROM TonKho 
    WHERE don_vi_id = NEW.don_vi_xuat_id AND duoc_pham_id = NEW.duoc_pham_id;

    -- 2. Bẫy lỗi an toàn: Lỡ kho đó hết hàng giữa chừng
    IF v_ton_kho_hien_tai IS NULL OR v_ton_kho_hien_tai < NEW.so_luong THEN 
        RAISE EXCEPTION 'Lỗi: Tồn kho tại nhà thuốc (ID: %) không đủ số lượng cho sản phẩm (ID: %)!', NEW.don_vi_xuat_id, NEW.duoc_pham_id; 
    END IF;

    -- 3. Trừ tồn kho trực tiếp
    UPDATE TonKho 
    SET so_luong_ton = so_luong_ton - NEW.so_luong 
    WHERE don_vi_id = NEW.don_vi_xuat_id AND duoc_pham_id = NEW.duoc_pham_id; 

    RETURN NEW; 
END; $$;


ALTER FUNCTION public.trg_tru_ton_kho() OWNER TO postgres;

--
-- Name: trg_update_diem_danh_gia(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_update_diem_danh_gia() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_duoc_pham_id INT;
BEGIN
    -- DELETE dùng OLD, INSERT/UPDATE dùng NEW
    v_duoc_pham_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.duoc_pham_id
                           ELSE NEW.duoc_pham_id
                      END;

    UPDATE DuocPham
    SET diem_danh_gia = COALESCE(
        (SELECT ROUND(AVG(so_sao)::NUMERIC, 1)
         FROM DanhGiaSanPham
         WHERE duoc_pham_id = v_duoc_pham_id),
        0.0
    )
    WHERE id = v_duoc_pham_id;

    -- Edge case: UPDATE đổi duoc_pham_id → cập nhật cả sản phẩm cũ
    IF TG_OP = 'UPDATE' AND OLD.duoc_pham_id <> NEW.duoc_pham_id THEN
        UPDATE DuocPham
        SET diem_danh_gia = COALESCE(
            (SELECT ROUND(AVG(so_sao)::NUMERIC, 1)
             FROM DanhGiaSanPham
             WHERE duoc_pham_id = OLD.duoc_pham_id),
            0.0
        )
        WHERE id = OLD.duoc_pham_id;
    END IF;

    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.trg_update_diem_danh_gia() OWNER TO postgres;

--
-- Name: trg_validate_phieu_tra_hang(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_validate_phieu_tra_hang() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_trang_thai VARCHAR(50);
BEGIN
    SELECT trang_thai_don INTO v_trang_thai
    FROM DonHang WHERE id = NEW.don_hang_id;

    IF v_trang_thai IS NULL THEN
        RAISE EXCEPTION 'Đơn hàng ID % không tồn tại!', NEW.don_hang_id;
    END IF;

    IF v_trang_thai NOT IN ('ChoHoanTat', 'TraHangMotPhan') THEN
        RAISE EXCEPTION 
            'Chỉ được tạo phiếu trả cho đơn đã hoàn thành hoặc trả một phần. Trạng thái hiện tại: %',
            v_trang_thai;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_validate_phieu_tra_hang() OWNER TO postgres;

