--
-- Name: view_diemnong_hanggia; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.view_diemnong_hanggia AS
 SELECT round((toa_do_lat)::numeric, 3) AS vung_lat,
    round((toa_do_lng)::numeric, 3) AS vung_lng,
    count(*) AS so_lan_canh_bao,
    count(DISTINCT hop_thuoc_uid) AS so_hop_thuoc_khac_nhau,
    count(DISTINCT ip_address) AS so_ip_khac_nhau,
    min(thoi_gian_quet) AS lan_dau_canh_bao,
    max(thoi_gian_quet) AS lan_cuoi_canh_bao,
    count(*) FILTER (WHERE (thoi_gian_quet >= (CURRENT_DATE - '30 days'::interval))) AS canh_bao_30_ngay_gan_nhat,
        CASE
            WHEN (count(*) >= 10) THEN 'NghiemTrong'::text
            WHEN (count(*) >= 5) THEN 'Cao'::text
            WHEN (count(*) >= 2) THEN 'TrungBinh'::text
            ELSE 'Thap'::text
        END AS muc_do_nguy_hiem
   FROM public.nhatkyxacthuc
  WHERE ((trang_thai_canh_bao = true) AND (toa_do_lat IS NOT NULL) AND (toa_do_lng IS NOT NULL))
  GROUP BY (round((toa_do_lat)::numeric, 3)), (round((toa_do_lng)::numeric, 3))
  ORDER BY (count(*)) DESC;


ALTER VIEW public.view_diemnong_hanggia OWNER TO postgres;

--
-- Name: view_doanhthu_theo_ngay; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.view_doanhthu_theo_ngay AS
 SELECT date(ngay_dat_hang) AS ngay,
    sum(
        CASE
            WHEN ((trang_thai_don)::text = 'HoanThanh'::text) THEN tong_tien
            ELSE (0)::numeric
        END) AS doanh_thu_thuc_te,
    sum(
        CASE
            WHEN ((trang_thai_don)::text = ANY (ARRAY[('ChoXacNhan'::character varying)::text, ('DaDongGoi'::character varying)::text, ('DangGiao'::character varying)::text, ('ChoHoanTat'::character varying)::text])) THEN tong_tien
            ELSE (0)::numeric
        END) AS doanh_thu_du_kien,
    count(
        CASE
            WHEN ((trang_thai_don)::text <> ALL (ARRAY[('DaHuy'::character varying)::text, ('TraHang'::character varying)::text, ('TraHangMotPhan'::character varying)::text])) THEN 1
            ELSE NULL::integer
        END) AS tong_so_don,
    count(
        CASE
            WHEN ((trang_thai_don)::text = 'HoanThanh'::text) THEN 1
            ELSE NULL::integer
        END) AS so_don_thanh_cong
   FROM public.donhang
  GROUP BY (date(ngay_dat_hang))
  ORDER BY (date(ngay_dat_hang)) DESC;


ALTER VIEW public.view_doanhthu_theo_ngay OWNER TO postgres;

--
-- Name: view_thuoc_can_date; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.view_thuoc_can_date AS
 SELECT lt.so_lo,
    dp.ten_thuoc,
    qc.ten_don_vi AS quy_cach,
    qc.gia_ban,
    lt.han_su_dung,
    (lt.han_su_dung - CURRENT_DATE) AS so_ngay_con_lai
   FROM ((public.lothuoc lt
     JOIN public.duocpham dp ON ((lt.duoc_pham_id = dp.id)))
     LEFT JOIN public.quycachdonggoi qc ON ((lt.quy_cach_id = qc.id)))
  WHERE ((lt.han_su_dung >= CURRENT_DATE) AND (lt.han_su_dung <= (CURRENT_DATE + 60)) AND ((lt.trang_thai)::text = 'HopLe'::text))
  ORDER BY lt.han_su_dung;


ALTER VIEW public.view_thuoc_can_date OWNER TO postgres;

--
-- Name: view_tonkho_chitiet; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.view_tonkho_chitiet AS
 SELECT dv.ten_don_vi,
    dp.ten_thuoc,
    qc.ten_don_vi AS don_vi_dong_goi,
    tk.so_luong_ton,
    ((tk.so_luong_ton)::numeric * qc.gia_ban) AS tong_gia_tri_ton
   FROM (((public.tonkho tk
     JOIN public.donvi dv ON ((tk.don_vi_id = dv.id)))
     JOIN public.duocpham dp ON ((tk.duoc_pham_id = dp.id)))
     JOIN public.quycachdonggoi qc ON ((tk.quy_cach_id = qc.id)))
  WHERE (tk.so_luong_ton > 0);


ALTER VIEW public.view_tonkho_chitiet OWNER TO postgres;

--
-- Name: view_truyvet_qr_khachhang; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.view_truyvet_qr_khachhang AS
 SELECT hop_thuoc_uid,
    thoi_gian,
        CASE
            WHEN ((loai_giao_dich)::text = 'KhoiTao'::text) THEN 'Xuất xưởng'::text
            WHEN (((loai_giao_dich)::text = 'NhapKho'::text) AND (den_don_vi_id IS NULL)) THEN 'Nhập kho kiểm định'::text
            WHEN (((loai_giao_dich)::text = 'NhapKho'::text) AND (den_don_vi_id IS NOT NULL)) THEN 'Tiếp nhận tại điểm phân phối'::text
            WHEN ((loai_giao_dich)::text = 'XuatKho'::text) THEN 'Luân chuyển phân phối'::text
            WHEN ((loai_giao_dich)::text = 'DongGoi'::text) THEN 'Chuẩn bị giao hàng'::text
            WHEN ((loai_giao_dich)::text = 'GiaoChoKhach'::text) THEN 'Đang vận chuyển'::text
            WHEN ((loai_giao_dich)::text = 'GiaoHangThanhCong'::text) THEN 'Giao hàng thành công'::text
            WHEN ((loai_giao_dich)::text = 'ThuHoi'::text) THEN 'Thu hồi kiểm tra'::text
            WHEN ((loai_giao_dich)::text = 'XuatHuy'::text) THEN 'Tiêu hủy'::text
            WHEN ((loai_giao_dich)::text = 'TraHang'::text) THEN 'Hoàn trả'::text
            ELSE 'Đang xử lý'::text
        END AS hanh_dong,
        CASE
            WHEN ((loai_giao_dich)::text = 'KhoiTao'::text) THEN 'Sản phẩm xuất xưởng từ nhà sản xuất, bắt đầu hành trình phân phối.'::text
            WHEN (((loai_giao_dich)::text = 'NhapKho'::text) AND (den_don_vi_id IS NULL)) THEN 'Sản phẩm được nhập kho và kiểm định chất lượng tại đơn vị phân phối.'::text
            WHEN (((loai_giao_dich)::text = 'NhapKho'::text) AND (den_don_vi_id IS NOT NULL)) THEN 'Sản phẩm đã được tiếp nhận tại điểm phân phối tiếp theo trong chuỗi cung ứng.'::text
            WHEN ((loai_giao_dich)::text = 'XuatKho'::text) THEN 'Sản phẩm được chuyển đến điểm phân phối tiếp theo trong chuỗi cung ứng.'::text
            WHEN ((loai_giao_dich)::text = 'DongGoi'::text) THEN 'Sản phẩm đã được đóng gói, sẵn sàng giao đến khách hàng.'::text
            WHEN ((loai_giao_dich)::text = 'GiaoChoKhach'::text) THEN 'Sản phẩm đang trong quá trình vận chuyển đến tay khách hàng.'::text
            WHEN ((loai_giao_dich)::text = 'GiaoHangThanhCong'::text) THEN 'Sản phẩm đã được giao thành công đến tay khách hàng.'::text
            WHEN ((loai_giao_dich)::text = 'ThuHoi'::text) THEN 'Sản phẩm được thu hồi để kiểm tra theo quy định.'::text
            WHEN ((loai_giao_dich)::text = 'XuatHuy'::text) THEN 'Sản phẩm đã được tiêu hủy theo quy trình xử lý dược phẩm.'::text
            WHEN ((loai_giao_dich)::text = 'TraHang'::text) THEN 'Sản phẩm được nhập lại hệ thống sau khi khách hàng hoàn trả.'::text
            ELSE 'Thông tin đang được cập nhật.'::text
        END AS thong_tin_chi_tiet
   FROM public.lichsuphanphoi;


ALTER VIEW public.view_truyvet_qr_khachhang OWNER TO postgres;

